#!/usr/bin/env node
// Renders subgraph.yaml from subgraph.template.yaml and config/<network>.json.
//
// graph-cli ships networks.json, which rewrites the address and start block of data sources that
// already exist in the manifest. That is not enough here: proving the schema is generic means
// indexing several unrelated vaults at once, and the number of data sources has to come from the
// configuration too. So the template carries exactly one data source and this repeats it.
//
// The generated file is not committed. It is a build artifact, and a committed copy would go stale
// against the config the moment anyone edited one and not the other.
import {readFileSync, writeFileSync} from "node:fs";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const network = process.argv[2];
if (!network) {
  console.error("usage: build-manifest.mjs <network>");
  console.error("       the network must match a file in config/, e.g. arc-testnet or base");
  process.exit(1);
}

const configPath = join(root, "config", `${network}.json`);
let config;
try {
  config = JSON.parse(readFileSync(configPath, "utf8"));
} catch (error) {
  console.error(`Cannot read ${configPath}: ${error.message}`);
  process.exit(1);
}

if (!Array.isArray(config.vaults) || config.vaults.length === 0) {
  console.error(`${configPath} lists no vaults.`);
  process.exit(1);
}

const template = readFileSync(join(root, "subgraph.template.yaml"), "utf8");
const marker = "dataSources:\n";
const split = template.indexOf(marker);
if (split === -1) {
  console.error("subgraph.template.yaml has no dataSources: block.");
  process.exit(1);
}

const header = template.slice(0, split + marker.length);
const block = template.slice(split + marker.length);

// A data source name becomes a generated TypeScript module, so it has to be a valid identifier and
// unique within the manifest. Catching a collision here beats a codegen error that names neither
// vault.
const names = new Set();
for (const vault of config.vaults) {
  if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(vault.name ?? "")) {
    console.error(`Vault name ${JSON.stringify(vault.name)} is not a valid identifier.`);
    process.exit(1);
  }
  if (names.has(vault.name)) {
    console.error(`Two vaults are both named ${vault.name}.`);
    process.exit(1);
  }
  names.add(vault.name);
}

const rendered = config.vaults
  .map((vault) =>
    block
      .replaceAll("{{name}}", vault.name)
      .replaceAll("{{network}}", config.network ?? network)
      .replaceAll("{{address}}", vault.address)
      .replaceAll("{{startBlock}}", String(vault.startBlock)),
  )
  .join("");

writeFileSync(join(root, "subgraph.yaml"), header + rendered);

// `graph codegen` writes one module per data source, named after it: generated/<name>/ERC4626.ts.
// One mapping file serves every vault, so it cannot import from a path that changes with the
// configuration. The generated classes are identical across data sources — same ABI, same events —
// so the mapping imports them through this shim and the shim points at whichever vault is first.
const first = config.vaults[0].name;
writeFileSync(
  join(root, "src", "bindings.ts"),
  [
    "// Generated by scripts/build-manifest.mjs. Do not edit, and do not commit.",
    "//",
    "// `graph codegen` names its output after each data source, so the import path changes with",
    "// the configuration. One mapping serves every vault, so it imports from here instead. The",
    "// classes are identical across data sources: same ABI, same events, same accessors.",
    `export {Deposit, Transfer, Withdraw, ERC4626} from "../generated/${first}/ERC4626";`,
    `export {ERC20} from "../generated/${first}/ERC20";`,
    "",
  ].join("\n"),
);

const plural = config.vaults.length === 1 ? "vault" : "vaults";
console.log(
  `subgraph.yaml: ${config.vaults.length} ${plural} on ${config.network ?? network} ` +
    `(${config.vaults.map((v) => v.name).join(", ")})`,
);
